#include <rocksdb/c.h>
#include <stdio.h>
int main(int argc,char**argv){if(argc!=2)return 2;char*err=0;rocksdb_options_t*o=rocksdb_options_create();rocksdb_t*d=rocksdb_open_for_read_only(o,argv[1],0,&err);if(err){fprintf(stderr,"%s\n",err);return 3;}rocksdb_readoptions_t*r=rocksdb_readoptions_create();rocksdb_iterator_t*i=rocksdb_create_iterator(d,r);for(rocksdb_iter_seek_to_first(i);rocksdb_iter_valid(i);rocksdb_iter_next(i)){size_t kn,vn;const char*k=rocksdb_iter_key(i,&kn),*v=rocksdb_iter_value(i,&vn);for(size_t j=0;j<kn;j++)printf("%02x",(unsigned char)k[j]);putchar('\t');for(size_t j=0;j<vn;j++)printf("%02x",(unsigned char)v[j]);putchar('\n');}rocksdb_iter_get_error(i,&err);int rc=err?4:0;rocksdb_iter_destroy(i);rocksdb_readoptions_destroy(r);rocksdb_close(d);rocksdb_options_destroy(o);return rc;}
